head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.LastJob = "";
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        await scwin.setCode();

        // 2009.09.01 채권공시 - 채권상장팀인경우..채권상장팀만 나오도록 셋팅한다.
        if (scwin.gDepCd === "2430") {
            cmb_DEP_CD.setValue(scwin.gDepCd);
        }
        await scwin.setHeader();
        await scwin.list();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(scwin.LastJob + " 실패");
        await $c.win.alert(trs_Save);
        dts_Save.Reset();
        dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31100.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert(scwin.LastJob + " 성공");
        dts_Save.Reset();
        dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
        await scwin.list();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31100.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.checkForm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31100.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31100.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31100.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name dts_Approv_Auth_List_OnLoadCompleted
 * @description dts_Approv_Auth_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Approv_Auth_List_OnLoadCompleted = function(rowcount) {
    try {
        // if (rowcount > 0)
        //    grd_Approv_Auth_List.AutoResizeAllCol(true);
        const vTotalCnt = rowcount;
        $c.stf.fillGridHeaderTotalCnt(vTotalCnt, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31100.dts_Approv_Auth_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        dts_EMP_NO.sort("DEP_CD", 0);
        // dts_EMP_NO.sort(); // W-Craft 주석처리
        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
        if (cmb_DEP_CD.getValue() === "") {
            cmb_EMP_NO.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31100.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        const vVal = cmb_DEP_CD.getValue();
        if (vVal === "") {
            // 전체일 경우
            return true;
        } else {
            const vVal2 = dts_EMP_NO.getCellData(row, "dep_cd"); // 전체.
            if (vVal2 === "") return true; // 전체.
            return (vVal === vVal2) ? true : false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF31100.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name grd_Approv_Auth_List_OnDblClick
 * @description grd_Approv_Auth_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Approv_Auth_List_OnDblClick = async function(row, colid) {
    try {
        await scwin.delete(row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31100.grd_Approv_Auth_List_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 2009.09.01 채권공시 - 채권상장팀인경우..전체를 밴다..
    if (js_bond_yn === "Y") {
        dts_DEP_CD.removeRow(1);
    }
};

/**
 * @method
 * @name setHeader
 * @description CUD용 Header
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    // CUD용 Header
    const sbmOptions = {
        id : "sbm_dts_Save",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Save.insertRow();
};

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function() {
    const sbmOptions = {
        id : "sbm_dts_Approv_Auth_List",
        action : "/DisclosureTransmitAuthority.do",
        ref : "",
        target : "dts_Approv_Auth_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert(dts_Approv_Auth_List.Text);

};

/**
 * @method
 * @name save
 * @description ********************************************************************
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    scwin.LastJob = "저장"; /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_INSERT;*/ X = TB_JOB_INSERT;
    dts_Save.setCellData(1, "LST_CHG_EMP_NO", scwin.gEmpNo);
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/DisclosureTransmitAuthority.do",
        ref : "dts_Save",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(row, colid) {
    if ((colid === "FUNC_DEL") &&
        (row > 0) &&
        (dts_Approv_Auth_List.getCellData(row, "FUNC_DEL") !== "")) {
        let res = window.confirm("삭제하시겠습니까?");
        if (res) {
            scwin.LastJob = "삭제";
            const str_AUTH_ENTRUST_USR_ID = dts_Approv_Auth_List.getCellData(row, "AUTH_ENTRUST_USR_ID");
            const str_AUTH_ENTRUSTED_USR_ID = dts_Approv_Auth_List.getCellData(row, "AUTH_ENTRUSTED_USR_ID");
            const str_AUTH_END_DD = dts_Approv_Auth_List.getCellData(row, "AUTH_END_DD");
            const str_AUTH_STRT_DD = dts_Approv_Auth_List.getCellData(row, "AUTH_STRT_DD");
            const str_LST_CHG_DDTM = dts_Approv_Auth_List.getCellData(row, "LST_CHG_DDTM");
            // alert(str_AUTH_ENTRUST_USR_ID + ", " + str_AUTH_ENTRUSTED_USR_ID + ", " + str_AUTH_END_DD + ", " + str_AUTH_STRT_DD);

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_DELETE;*/
            X = TB_JOB_DELETE;
            dts_Save.setCellData(1, "AUTH_ENTRUST_USR_ID", str_AUTH_ENTRUST_USR_ID);
            dts_Save.setCellData(1, "AUTH_ENTRUSTED_USR_ID", str_AUTH_ENTRUSTED_USR_ID);
            dts_Save.setCellData(1, "AUTH_END_DD", str_AUTH_END_DD);
            dts_Save.setCellData(1, "AUTH_STRT_DD", str_AUTH_STRT_DD);
            dts_Save.setCellData(1, "LST_CHG_DDTM", str_LST_CHG_DDTM);

            // alert_parse(dts_Save.Text, ",");return;

            // alert(dts_Save.Text);

            trs_Save.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/DisclosureTransmitAuthority.do",
                ref : "dts_Save",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (cmb_DEP_CD.getValue() === "") {
        await $c.win.alert("[팀]을 선택하세요.");
        cmb_DEP_CD.focus();
        return;
    }
    if (cmb_EMP_NO.getValue() === "") {
        await $c.win.alert("[담당자]을 선택하세요.");
        cmb_EMP_NO.focus();
        return;
    }
    if (edt_SDate.getValue() === "") {
        await $c.win.alert("[시작일시]를 입력하세요.");
        edt_SDate.focus();
        return;
    }
    if (edt_EDate.getValue() === "") {
        await $c.win.alert("[만료일시]를 입력하세요.");
        edt_EDate.focus();
        return;
    }
    if (txb_Reason.getValue() === "") {
        await $c.win.alert("[사유]를 입력하세요.");
        txb_Reason.focus();
        return;
    }
    let res = window.confirm("저장하시겠습니까?");
    if (res) {
        await scwin.save();
    }
};
